# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_brev_a import AB
AR=[['拉丁 brevis → abbreviare','短 → 缩短'],['古法语 abregier／abrigier → 英语 abridge','删去部分，使内容缩短']]
W=[
E('abbreviate','/əˈbriːvieɪt/','缩写；缩短','把一个较长的名称或表达压成更短的形式。','来自拉丁 abbreviare“缩短”的相关形式；ab- 常分析为 ad- 在 b 前的同化，不宜简单记成“拿走一个词根”。',AB,'abbreviate a name 是把名字写短；abbreviate as 后面放缩写结果。用缩写通常为了节省空间或避免反复写长词，但读者必须知道它代表什么，否则短了也不清楚。','abbreviate X as Y；be abbreviated to；abbreviate a title。','abbreviate 常用于词或名称的缩写；abridge 常用于文章、书等较大内容的删节。',('The company name is abbreviated as NTS.','公司名称缩写为 NTS。'),('Please do not abbreviate your name on this form.','请不要在这张表格上缩写你的姓名。'),sources=['https://www.etymonline.com/word/abbreviate','https://en.wiktionary.org/wiki/abbreviate']),
E('abbreviation','/əˌbriːviˈeɪʃən/','缩写、缩略形式；缩短','把长表达压短后得到的那个形式，也可以说压短这件事。','经法语或晚期拉丁 abbreviatio 进入英语；记录早于英语动词 abbreviate，不能把历史写成英语动词先加 -ion 才有名词。',[['拉丁 abbreviare → abbreviatio','缩短 → 缩短行为'],['法语／英语 abbreviation','缩短；词语的缩写形式']],'例如 Jan. 表示 January，就可以称为 abbreviation。这个词在一般用法中很宽，首字母缩写也常放在缩略语的范围里。专业写作可能再细分 acronym、initialism 等，但不必让这些标签挡住“长形式变短”的核心。','an abbreviation for；a common abbreviation；avoid unexplained abbreviations。','abbreviation 是缩略形式；summary 是内容摘要，不只是把一个名称少写几个字母。',('“Jan.” is a common abbreviation for January.','Jan. 是 January 的常见缩写。'),('The guide explains every abbreviation used in the report.','指南解释了报告中使用的每一个缩略语。'),sources=['https://www.etymonline.com/word/abbreviation','https://en.wiktionary.org/wiki/abbreviation']),
E('abbreviated','/əˈbriːvieɪtɪd/','缩写的；简化、缩短了的','原本更长，现在换成了一个短版本。','abbreviate + -ed，作过去分词或形容词；词尾 /t/ 后的 -ed 读 /ɪd/。',AB+[['abbreviate + -ed → abbreviated','已经缩写或缩短的']],'an abbreviated title 是缩写标题，an abbreviated schedule 是缩短了的日程。它也能修饰程序、版本等，不只限于几个字母。不过短版本可能省掉细节，不保证足够应对所有用途。','an abbreviated form；an abbreviated version；an abbreviated schedule。','abbreviated 是缩短后的，brief 直接说短。某物本来就短，不一定经历过 abbreviation。',('The badge shows an abbreviated version of the organisation’s name.','徽章上显示的是机构名称的缩写形式。'),('Because of the storm, the festival followed an abbreviated schedule.','由于暴风雨，节庆采用了缩短的活动日程。'),sources=['https://en.wiktionary.org/wiki/abbreviated','https://www.etymonline.com/word/abbreviate']),
E('abridge','/əˈbrɪdʒ/','删节、节略；限制、削减','从一整段内容里删掉一些部分，让整体变短。','与 abbreviate 同出拉丁 abbreviare，但经古法语 abregier／abrigier 发生了不同的音形变化。不是 a + bridge“桥”。',AR,'abridge a novel 是把小说删节成较短版本，通常仍保留故事主线，而不是只写几句摘要。较正式语境中的 abridge rights 则是削减权利，这里是范围被缩短，不是文字被缩写。','abridge a book；abridge a text；abridge rights。','abbreviate 常缩写名称，abridge 常删节长内容；summarize 是概括要点，产物不一定仍是原文删节版。',('The publisher decided to abridge the memoir for younger readers.','出版方决定把回忆录删节成适合较年轻读者的版本。'),('The editor was asked to abridge the speech without changing its main argument.','编辑被要求缩短演讲稿，同时保留主要论点。'),sources=['https://www.etymonline.com/word/abridge','https://en.wiktionary.org/wiki/abridge']),
E('abridged','/əˈbrɪdʒd/','删节过的；节略的','手里的书或录音仍是那部作品，但部分内容已经被删去。','abridge + -ed，常作为版本标签；末尾读 /d/，不是 /ɪd/。',AR+[['abridge + -ed → abridged','已删去部分内容的']],'an abridged audiobook 是删节版有声书，可能删掉描写或支线来缩短时长。它不一定差，只是用途不同；如果你要逐段对照原书，就要留意版本是否 abridged。','an abridged edition；an abridged audiobook；an abridged version。','abridged 是经过删节，adapted 是改编；一部作品可能既删节又改编，也可能只做其中一种。',('We read an abridged edition of the novel in class.','我们在课堂上读了那部小说的删节版。'),('The abridged audiobook is much shorter than the original recording.','删节版有声书比原版录音短得多。'),sources=['https://en.wiktionary.org/wiki/abridged','https://www.etymonline.com/word/abridge']),
E('unabridged','/ˌʌnəˈbrɪdʒd/','未删节的；完整版本的','原来作品的内容保留下来，没有为了缩短而删掉部分。','un-“不” + abridged“删节的”；否定的是删节状态。',AR+[['abridged → unabridged','删节的 → 未删节的']],'unabridged 常出现在书籍或有声书说明上，告诉你这是未删节版本。它并不保证没有翻译、排版或编辑校订，也不等于词典收录了世上每一个词；它说明的是相对于相关完整版本的删节情况。','an unabridged edition；an unabridged audiobook；the unabridged text。','unabridged 主要与删节版相对；original 可能说原作、原语言或最初版本，两者不是完全同义。',('I chose the unabridged audiobook because I wanted the whole story.','我选择了未删节版有声书，因为我想听完整的故事。'),('The library has an unabridged edition of the diary.','图书馆藏有这部日记的未删节版。'),sources=['https://en.wiktionary.org/wiki/unabridged','https://www.etymonline.com/word/unabridged']),
]
